from pathlib import Path
from collections import defaultdict
from datetime import date, timedelta
import csv, re

ref = date(2025, 8, 12)
windows = {
    'today': (ref, ref),
    'last_7_days': (ref - timedelta(days=6), ref),
    'last_30_days': (ref - timedelta(days=29), ref),
    'month_to_date': (date(ref.year, ref.month, 1), ref),
    'total': (date(1900,1,1), date(9999,12,31)),
}
severities = ['ERROR','WARNING','INFO']
counts = {p: {s: 0 for s in severities} for p in windows}

for path in sorted(Path('/app/logs').glob('*.log')):
    m = re.match(r'(\d{4})-(\d{2})-(\d{2})_.+\.log$', path.name)
    if not m:
        continue
    y, mo, d = map(int, m.groups())
    fdate = date(y, mo, d)
    line_counts = {s: 0 for s in severities}
    with path.open('r', encoding='utf-8', errors='replace') as f:
        for line in f:
            for s in severities:
                if f'[{s}]' in line:
                    line_counts[s] += 1
    for period, (start, end) in windows.items():
        if start <= fdate <= end:
            for s in severities:
                counts[period][s] += line_counts[s]

out = Path('/app/summary.csv')
with out.open('w', newline='', encoding='utf-8') as f:
    w = csv.writer(f)
    w.writerow(['period','severity','count'])
    for period in ['today','last_7_days','last_30_days','month_to_date','total']:
        for s in severities:
            w.writerow([period,s,counts[period][s]])

print('WROTE', out)
for period in ['today','last_7_days','last_30_days','month_to_date','total']:
    print(period, counts[period])
